/**
 * The plugin tool catalog must not list two tools under the same name.
 *
 * MCP clients route tools/call by name, so a duplicate makes one tool
 * unreachable. The catalog is generated by `bun run gen:tool-catalog` and
 * committed as servers/_tool-catalog.json; this test loads that file and
 * fails on any repeated name. The duplicate detector is also exercised on
 * synthetic input so a regression in the detector itself cannot pass silently.
 */

import { describe, expect, test } from "bun:test";
import catalog from "../servers/_tool-catalog.json" with { type: "json" };

interface NamedTool {
  name: unknown;
}

/** Names that appear more than once, in first-seen order, each listed once. */
function duplicateToolNames(tools: readonly NamedTool[]): string[] {
  const seen = new Set<unknown>();
  const duplicates = new Set<string>();
  for (const tool of tools) {
    if (seen.has(tool.name)) duplicates.add(String(tool.name));
    seen.add(tool.name);
  }
  return [...duplicates];
}

describe("plugin tool catalog names", () => {
  test("catalog is non-empty and every tool has a string name", () => {
    expect(catalog.length).toBeGreaterThan(0);
    const unnamed = catalog.filter((tool) => typeof tool.name !== "string" || !tool.name);
    expect(unnamed).toEqual([]);
  });

  test("no two catalog tools share a name", () => {
    expect(duplicateToolNames(catalog)).toEqual([]);
  });

  test("duplicate detector reports each repeated name once", () => {
    expect(duplicateToolNames([{ name: "a" }, { name: "b" }])).toEqual([]);
    expect(duplicateToolNames([{ name: "a" }, { name: "a" }])).toEqual(["a"]);
    expect(duplicateToolNames([{ name: "a" }, { name: "b" }, { name: "a" }, { name: "b" }, { name: "a" }])).toEqual([
      "a",
      "b",
    ]);
  });
});
